function extractText(j) {
  if (Array.isArray(j.output)) {
    for (const o of j.output) {
      const part = Array.isArray(o.content) && o.content.find(c => c.text);
      if (part?.text) return part.text;
    }
  }
  if (Array.isArray(j.content)) {
    const part = j.content.find(c => c.text);
    if (part?.text) return part.text;
  }
  return j.message?.content ?? j.content ?? j.text ?? '';
}

const RUBRICS = ['price', 'swap', 'recipe'];
const outs = $('Scout (Django)').first().json.outliers;
const raw = String(extractText($input.first().json) || '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { throw new Error('LLM вернул не JSON: ' + raw.slice(0, 300)); }
const rows = (parsed.topics || [])
  // Вторая линия после промпта: без конкретики из текста донора пост выходит водой (#28, «Чай со сладким»).
  .filter(t => t.verdict === 'ok' && t.title && outs[t.i] && RUBRICS.includes(t.rubric) && (t.facts || '').trim())
  .map(t => {
    const o = outs[t.i];
    return {
      title: String(t.title).trim(),
      rubric: t.rubric,
      angle: t.angle || null,
      facts: t.facts.trim(),
      note: `донор @${o.source}: ×${o.score} к медиане канала, ${o.views} просмотров, ${o.reactions} реакций`,
      source_url: o.url,
      score: o.score,
    };
  });
const skipped = (parsed.topics || []).filter(t => t.verdict !== 'ok').map(t => `#${t.i}: ${t.reason}`);
return [{ json: { rows, count: rows.length, skipped } }];
